  1→import { useState, useCallback, useMemo, useEffect } from "react";
  2→import type {
  3→  ActionFunctionArgs,
  4→  HeadersFunction,
  5→  LoaderFunctionArgs,
  6→} from "react-router";
  7→import { useFetcher, useLoaderData, useNavigate } from "react-router";
  8→import { useAppBridge } from "@shopify/app-bridge-react";
  9→import { authenticate } from "../shopify.server";
 10→import { boundary } from "@shopify/shopify-app-react-router/server";
 11→import db from "../db.server";
 12→import {
 13→  Page,
 14→  Layout,
 15→  Card,
 16→  BlockStack,
 17→  InlineStack,
 18→  Text,
 19→  Button,
 20→  TextField,
 21→  Select,
 22→  Modal,
 23→  DataTable,
 24→  EmptyState,
 25→  Divider,
 26→  Box,
 27→  Tooltip,
 28→  Icon,
 29→  Banner,
 30→  Pagination,
 31→  InlineGrid,
 32→} from "@shopify/polaris";
 33→import {
 34→  SearchIcon,
 35→  DeleteIcon,
 36→  PlusIcon,
 37→  EmailIcon,
 38→} from "@shopify/polaris-icons";
 39→
 40→const PAGE_SIZE = 10;
 41→
 42→export const loader = async ({ request }: LoaderFunctionArgs) => {
 43→  const { session } = await authenticate.admin(request);
 44→  const shop = session.shop;
 45→
 46→  const entries = await db.waitlistEntry.findMany({
 47→    where: { shop },
 48→    orderBy: { createdAt: "desc" },
 49→  });
 50→
 51→  const stats = {
 52→    total: entries.length,
 53→    waiting: entries.filter((e) => e.status === "waiting").length,
 54→    notified: entries.filter((e) => e.status === "notified").length,
 55→    converted: entries.filter((e) => e.status === "converted").length,
 56→    uniqueZips: [...new Set(entries.map((e) => e.zipCode))].length,
 57→  };
 58→
 59→  return { entries, stats };
 60→};
 61→
 62→export const action = async ({ request }: ActionFunctionArgs) => {
 63→  const { session } = await authenticate.admin(request);
 64→  const shop = session.shop;
 65→  const formData = await request.formData();
 66→  const intent = formData.get("intent");
 67→
 68→  if (intent === "add") {
 69→    const email = String(formData.get("email") || "").trim().toLowerCase();
 70→    const zipCode = String(formData.get("zipCode") || "")
 71→      .trim()
 72→      .toUpperCase();
 73→    const note = String(formData.get("note") || "").trim() || null;
 74→
 75→    if (!email || !zipCode) return { error: "Email and zip code are required." };
 76→
 77→    try {
 78→      await db.waitlistEntry.create({
 79→        data: { shop, email, zipCode, note },
 80→      });
 81→      return { success: true, action: "added" };
 82→    } catch {
 83→      return { error: "This email is already on the waitlist for this zip code." };
 84→    }
 85→  }
 86→
 87→  if (intent === "delete") {
 88→    const id = String(formData.get("id"));
 89→    await db.waitlistEntry.delete({ where: { id } });
 90→    return { success: true, action: "deleted" };
 91→  }
 92→
 93→  if (intent === "update-status") {
 94→    const id = String(formData.get("id"));
 95→    const status = String(formData.get("status"));
 96→    await db.waitlistEntry.update({ where: { id }, data: { status } });
 97→    return { success: true, action: "updated" };
 98→  }
 99→
100→  if (intent === "bulk-notify") {
101→    const zipCode = String(formData.get("zipCode") || "")
102→      .trim()
103→      .toUpperCase();
104→    if (!zipCode) return { error: "Zip code is required." };
105→
106→    const updated = await db.waitlistEntry.updateMany({
107→      where: { shop, zipCode, status: "waiting" },
108→      data: { status: "notified" },
109→    });
110→
111→    return {
112→      success: true,
113→      action: "bulk-notify",
114→      count: updated.count,
115→      zipCode,
116→    };
117→  }
118→
119→  if (intent === "notify-zip") {
120→    const zipCode = String(formData.get("zipCode") || "").trim().toUpperCase();
121→    if (!zipCode) return { error: "No ZIP code specified." };
122→
123→    const entries = await db.waitlistEntry.findMany({
124→      where: { shop, zipCode, status: "waiting" },
125→      select: { id: true, email: true },
126→    });
127→
128→    if (entries.length === 0) {
129→      return { action: "notify-zip", zipCode, emails: [] as string[], count: 0 };
130→    }
131→
132→    await db.waitlistEntry.updateMany({
133→      where: { shop, zipCode, status: "waiting" },
134→      data: { status: "notified" },
135→    });
136→
137→    const emails = entries.map((e) => e.email);
138→    return { action: "notify-zip", zipCode, emails, count: emails.length };
139→  }
140→
141→  if (intent === "delete-all-notified") {
142→    const deleted = await db.waitlistEntry.deleteMany({
143→      where: { shop, status: "notified" },
144→    });
145→    return { success: true, action: "deleted-notified", count: deleted.count };
146→  }
147→
148→  return null;
149→};
150→
151→type WaitlistEntry = {
152→  id: string;
153→  email: string;
154→  zipCode: string;
155→  note: string | null;
156→  status: string;
157→  createdAt: string | Date;
158→};
159→
160→export default function WaitlistPage() {
161→  const { entries, stats } = useLoaderData<typeof loader>();
162→  const fetcher = useFetcher<typeof action>();
163→  const shopify = useAppBridge();
164→  const navigate = useNavigate();
165→
166→  const [searchQuery, setSearchQuery] = useState("");
167→  const [statusFilter, setStatusFilter] = useState("all");
168→  const [currentPage, setCurrentPage] = useState(1);
169→  const [addModalOpen, setAddModalOpen] = useState(false);
170→  const [notifyModalOpen, setNotifyModalOpen] = useState(false);
171→  const [notifyResultModalOpen, setNotifyResultModalOpen] = useState(false);
172→  const [notifyResult, setNotifyResult] = useState<{
173→    zipCode: string;
174→    emails: string[];
175→    count: number;
176→  } | null>(null);
177→  const [copySuccess, setCopySuccess] = useState(false);
178→
179→  // Form state
180→  const [newEmail, setNewEmail] = useState("");
181→  const [newZipCode, setNewZipCode] = useState("");
182→  const [newNote, setNewNote] = useState("");
183→  const [notifyZip, setNotifyZip] = useState("");
184→
185→  const actionError =
186→    fetcher.data && "error" in fetcher.data ? fetcher.data.error : null;
187→
188→  useEffect(() => {
189→    if (
190→      fetcher.data &&
191→      "action" in fetcher.data &&
192→      fetcher.data.action === "notify-zip"
193→    ) {
194→      const data = fetcher.data as {
195→        action: string;
196→        zipCode: string;
197→        emails: string[];
198→        count: number;
199→      };
200→      setNotifyResult({ zipCode: data.zipCode, emails: data.emails, count: data.count });
201→      setNotifyResultModalOpen(true);
202→    }
203→  }, [fetcher.data]);
204→
205→  const filteredEntries = useMemo(() => {
206→    let filtered = entries as WaitlistEntry[];
207→    if (searchQuery.trim()) {
208→      const q = searchQuery.trim().toLowerCase();
209→      filtered = filtered.filter(
210→        (e) =>
211→          e.email.toLowerCase().includes(q) ||
212→          e.zipCode.toLowerCase().includes(q) ||
213→          (e.note && e.note.toLowerCase().includes(q)),
214→      );
215→    }
216→    if (statusFilter !== "all") {
217→      filtered = filtered.filter((e) => e.status === statusFilter);
218→    }
219→    return filtered;
220→  }, [entries, searchQuery, statusFilter]);
221→
222→  const totalPages = Math.max(1, Math.ceil(filteredEntries.length / PAGE_SIZE));
223→  const paginatedEntries = useMemo(() => {
224→    const start = (currentPage - 1) * PAGE_SIZE;
225→    return filteredEntries.slice(start, start + PAGE_SIZE);
226→  }, [filteredEntries, currentPage]);
227→
228→  const handleSearchChange = useCallback((val: string) => {
229→    setSearchQuery(val);
230→    setCurrentPage(1);
231→  }, []);
232→
233→  const handleFilterChange = useCallback((val: string) => {
234→    setStatusFilter(val);
235→    setCurrentPage(1);
236→  }, []);
237→
238→  const handleAdd = useCallback(() => {
239→    if (!newEmail.trim() || !newZipCode.trim()) return;
240→    const fd = new FormData();
241→    fd.set("intent", "add");
242→    fd.set("email", newEmail);
243→    fd.set("zipCode", newZipCode);
244→    fd.set("note", newNote);
245→    fetcher.submit(fd, { method: "POST" });
246→    setNewEmail("");
247→    setNewZipCode("");
248→    setNewNote("");
249→    setAddModalOpen(false);
250→    shopify.toast.show("Added to waitlist");
251→  }, [newEmail, newZipCode, newNote, fetcher, shopify]);
252→
253→  const handleDelete = useCallback(
254→    (id: string) => {
255→      const fd = new FormData();
256→      fd.set("intent", "delete");
257→      fd.set("id", id);
258→      fetcher.submit(fd, { method: "POST" });
259→      shopify.toast.show("Entry removed");
260→    },
261→    [fetcher, shopify],
262→  );
263→
264→  const handleStatusChange = useCallback(
265→    (id: string, status: string) => {
266→      const fd = new FormData();
267→      fd.set("intent", "update-status");
268→      fd.set("id", id);
269→      fd.set("status", status);
270→      fetcher.submit(fd, { method: "POST" });
271→    },
272→    [fetcher],
273→  );
274→
275→  const handleBulkNotify = useCallback(() => {
276→    if (!notifyZip.trim()) return;
277→    const fd = new FormData();
278→    fd.set("intent", "notify-zip");
279→    fd.set("zipCode", notifyZip);
280→    fetcher.submit(fd, { method: "POST" });
281→    setNotifyModalOpen(false);
282→    setNotifyZip("");
283→  }, [notifyZip, fetcher]);
284→
285→  const handleCopyEmails = useCallback(() => {
286→    if (!notifyResult) return;
287→    navigator.clipboard.writeText(notifyResult.emails.join(", ")).then(() => {
288→      setCopySuccess(true);
289→      setTimeout(() => setCopySuccess(false), 2000);
290→    });
291→  }, [notifyResult]);
292→
293→  const handleDeleteNotified = useCallback(() => {
294→    const fd = new FormData();
295→    fd.set("intent", "delete-all-notified");
296→    fetcher.submit(fd, { method: "POST" });
297→    shopify.toast.show("Notified entries cleared");
298→  }, [fetcher, shopify]);
299→
300→  // Compute per-ZIP waiting counts for the "Notify Waitlist" section
301→  const zipWaitingCounts = useMemo(() => {
302→    const map = new Map<string, number>();
303→    for (const e of entries as WaitlistEntry[]) {
304→      if (e.status === "waiting") {
305→        map.set(e.zipCode, (map.get(e.zipCode) ?? 0) + 1);
306→      }
307→    }
308→    return Array.from(map.entries())
309→      .map(([zipCode, count]) => ({ zipCode, count }))
310→      .sort((a, b) => b.count - a.count);
311→  }, [entries]);
312→
313→  const handleNotifyZip = useCallback(
314→    (zipCode: string) => {
315→      const fd = new FormData();
316→      fd.set("intent", "notify-zip");
317→      fd.set("zipCode", zipCode);
318→      fetcher.submit(fd, { method: "POST" });
319→    },
320→    [fetcher],
321→  );
322→
323→  const statusOptions = [
324→    { label: "Waiting", value: "waiting" },
325→    { label: "Notified", value: "notified" },
326→    { label: "Converted", value: "converted" },
327→  ];
328→
329→  const filterOptions = [
330→    { label: "All", value: "all" },
331→    { label: "Waiting", value: "waiting" },
332→    { label: "Notified", value: "notified" },
333→    { label: "Converted", value: "converted" },
334→  ];
335→
336→  const formatDate = (d: string | Date) => {
337→    const date = new Date(d);
338→    return date.toLocaleDateString("en-US", {
339→      month: "short",
340→      day: "numeric",
341→      year: "numeric",
342→    });
343→  };
344→
345→  const tableRows = paginatedEntries.map((entry) => [
346→    <Text as="span" fontWeight="semibold" key={`email-${entry.id}`}>
347→      {entry.email}
348→    </Text>,
349→    <Text as="span" fontWeight="bold" key={`zip-${entry.id}`}>
350→      {entry.zipCode}
351→    </Text>,
352→    <div key={`status-${entry.id}`} style={{ minWidth: "120px" }}>
353→      <Select
354→        label="Status"
355→        labelHidden
356→        options={statusOptions}
357→        value={entry.status}
358→        onChange={(val) => handleStatusChange(entry.id, val)}
359→      />
360→    </div>,
361→    entry.note || (
362→      <Text as="span" tone="subdued">
363→        —
364→      </Text>
365→    ),
366→    formatDate(entry.createdAt),
367→    <Tooltip content="Remove from waitlist" key={`del-${entry.id}`}>
368→      <Button
369→        size="slim"
370→        variant="tertiary"
371→        tone="critical"
372→        onClick={() => handleDelete(entry.id)}
373→        icon={DeleteIcon}
374→        accessibilityLabel="Delete"
375→      />
376→    </Tooltip>,
377→  ]);
378→
379→  return (
380→    <Page
381→      title="Customer Waitlist"
382→      subtitle="Customers waiting for delivery availability in their area"
383→      backAction={{ onAction: () => navigate("/app") }}
384→      primaryAction={{
385→        content: "Add Entry",
386→        icon: PlusIcon,
387→        onAction: () => setAddModalOpen(true),
388→      }}
389→      secondaryActions={[
390→        {
391→          content: "Notify by ZIP",
392→          icon: EmailIcon,
393→          onAction: () => setNotifyModalOpen(true),
394→        },
395→      ]}
396→    >
397→      <Box paddingBlockEnd="1600">
398→      <Layout>
399→        {/* Stats */}
400→        <Layout.Section>
401→          <InlineGrid columns={{ xs: 2, sm: 2, md: 5 }} gap="400">
402→            <Box
403→              padding="400"
404→              background="bg-surface"
405→              borderWidth="025"
406→              borderColor="border"
407→              borderRadius="200"
408→            >
409→              <BlockStack gap="100">
410→                <Text as="p" tone="subdued" variant="bodySm">
411→                  Total
412→                </Text>
413→                <Text as="p" variant="headingXl" fontWeight="bold">
414→                  {stats.total}
415→                </Text>
416→              </BlockStack>
417→            </Box>
418→            <Box
419→              padding="400"
420→              background="bg-surface-warning"
421→              borderWidth="025"
422→              borderColor="border-warning"
423→              borderRadius="200"
424→            >
425→              <BlockStack gap="100">
426→                <Text as="p" tone="caution" variant="bodySm">
427→                  Waiting
428→                </Text>
429→                <Text as="p" variant="headingXl" fontWeight="bold" tone="caution">
430→                  {stats.waiting}
431→                </Text>
432→              </BlockStack>
433→            </Box>
434→            <Box
435→              padding="400"
436→              background="bg-surface-info"
437→              borderWidth="025"
438→              borderColor="border-info"
439→              borderRadius="200"
440→            >
441→              <BlockStack gap="100">
442→                <Text as="p" tone="subdued" variant="bodySm">
443→                  Notified
444→                </Text>
445→                <Text as="p" variant="headingXl" fontWeight="bold">
446→                  {stats.notified}
447→                </Text>
448→              </BlockStack>
449→            </Box>
450→            <Box
451→              padding="400"
452→              background="bg-surface-success"
453→              borderWidth="025"
454→              borderColor="border-success"
455→              borderRadius="200"
456→            >
457→              <BlockStack gap="100">
458→                <Text as="p" tone="success" variant="bodySm">
459→                  Converted
460→                </Text>
461→                <Text as="p" variant="headingXl" fontWeight="bold" tone="success">
462→                  {stats.converted}
463→                </Text>
464→              </BlockStack>
465→            </Box>
466→            <Box
467→              padding="400"
468→              background="bg-surface"
469→              borderWidth="025"
470→              borderColor="border"
471→              borderRadius="200"
472→            >
473→              <BlockStack gap="100">
474→                <Text as="p" tone="subdued" variant="bodySm">
475→                  Unique Zips
476→                </Text>
477→                <Text as="p" variant="headingXl" fontWeight="bold">
478→                  {stats.uniqueZips}
479→                </Text>
480→              </BlockStack>
481→            </Box>
482→          </InlineGrid>
483→        </Layout.Section>
484→
485→        {/* Per-ZIP Notify Section */}
486→        {zipWaitingCounts.length > 0 && (
487→          <Layout.Section>
488→            <Card>
489→              <BlockStack gap="400">
490→                <BlockStack gap="100">
491→                  <Text as="h2" variant="headingMd" fontWeight="semibold">
492→                    Notify Waiting Customers by ZIP Code
493→                  </Text>
494→                  <Text as="p" tone="subdued" variant="bodySm">
495→                    Select a ZIP code to retrieve all waiting customer emails
496→                    and mark them as notified in one click.
497→                  </Text>
498→                </BlockStack>
499→                <Divider />
500→                <BlockStack gap="300">
501→                  {zipWaitingCounts.map(({ zipCode, count }) => (
502→                    <InlineStack
503→                      key={zipCode}
504→                      align="space-between"
505→                      blockAlign="center"
506→                      gap="300"
507→                      wrap={false}
508→                    >
509→                      <InlineStack gap="300" blockAlign="center">
510→                        <Text as="span" fontWeight="bold">
511→                          {zipCode}
512→                        </Text>
513→                        <Text as="span" tone="subdued" variant="bodySm">
514→                          {count} customer{count === 1 ? "" : "s"} waiting
515→                        </Text>
516→                      </InlineStack>
517→                      <Button
518→                        size="slim"
519→                        icon={EmailIcon}
520→                        onClick={() => handleNotifyZip(zipCode)}
521→                        loading={fetcher.state !== "idle"}
522→                      >
523→                        {`Notify ${count} Customer${count === 1 ? "" : "s"}`}
524→                      </Button>
525→                    </InlineStack>
526→                  ))}
527→                </BlockStack>
528→              </BlockStack>
529→            </Card>
530→          </Layout.Section>
531→        )}
532→
533→        {/* Waitlist Table */}
534→        <Layout.Section>
535→          <Card padding="0">
536→            <Box padding="400">
537→              <InlineStack
538→                gap="300"
539→                align="space-between"
540→                blockAlign="center"
541→                wrap
542→              >
543→                <InlineStack gap="300" blockAlign="center" wrap>
544→                  <div style={{ minWidth: "260px" }}>
545→                    <TextField
546→                      label="Search"
547→                      labelHidden
548→                      value={searchQuery}
549→                      onChange={handleSearchChange}
550→                      placeholder="Search by email or zip code..."
551→                      autoComplete="off"
552→                      prefix={<Icon source={SearchIcon} />}
553→                      clearButton
554→                      onClearButtonClick={() => handleSearchChange("")}
555→                    />
556→                  </div>
557→                  <div style={{ minWidth: "120px" }}>
558→                    <Select
559→                      label="Status"
560→                      labelHidden
561→                      options={filterOptions}
562→                      value={statusFilter}
563→                      onChange={handleFilterChange}
564→                    />
565→                  </div>
566→                </InlineStack>
567→                <InlineStack gap="200">
568→                  {stats.notified > 0 && (
569→                    <Button
570→                      tone="critical"
571→                      variant="plain"
572→                      onClick={handleDeleteNotified}
573→                    >
574→                      {`Clear notified (${stats.notified})`}
575→                    </Button>
576→                  )}
577→                  <Button
578→                    variant="primary"
579→                    icon={PlusIcon}
580→                    onClick={() => setAddModalOpen(true)}
581→                  >
582→                    Add Entry
583→                  </Button>
584→                </InlineStack>
585→              </InlineStack>
586→            </Box>
587→            <Divider />
588→
589→            {(entries as WaitlistEntry[]).length === 0 ? (
590→              <EmptyState
591→                heading="No customers on the waitlist yet"
592→                image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
593→                action={{
594→                  content: "Add first entry",
595→                  onAction: () => setAddModalOpen(true),
596→                }}
597→              >
598→                <p>
599→                  When customers enter a zip code that isn&apos;t in your delivery
600→                  area, they can join the waitlist. You can also manually add
601→                  entries here. Enable the waitlist on blocked zip codes in your
602→                  Widget settings.
603→                </p>
604→              </EmptyState>
605→            ) : filteredEntries.length === 0 ? (
606→              <Box padding="600">
607→                <BlockStack gap="200" inlineAlign="center">
608→                  <Text as="p" tone="subdued" alignment="center">
609→                    No entries match your search.
610→                  </Text>
611→                  <Button
612→                    variant="plain"
613→                    onClick={() => {
614→                      setSearchQuery("");
615→                      setStatusFilter("all");
616→                    }}
617→                  >
618→                    Clear filters
619→                  </Button>
620→                </BlockStack>
621→              </Box>
622→            ) : (
623→              <>
624→                <DataTable
625→                  columnContentTypes={[
626→                    "text",
627→                    "text",
628→                    "text",
629→                    "text",
630→                    "text",
631→                    "text",
632→                  ]}
633→                  headings={[
634→                    "Email",
635→                    "Zip Code",
636→                    "Status",
637→                    "Note",
638→                    "Date",
639→                    "Actions",
640→                  ]}
641→                  rows={tableRows}
642→                  hoverable
643→                />
644→                {totalPages > 1 && (
645→                  <Box padding="400">
646→                    <InlineStack align="center" blockAlign="center" gap="300">
647→                      <Pagination
648→                        hasPrevious={currentPage > 1}
649→                        onPrevious={() =>
650→                          setCurrentPage((p) => Math.max(1, p - 1))
651→                        }
652→                        hasNext={currentPage < totalPages}
653→                        onNext={() =>
654→                          setCurrentPage((p) => Math.min(totalPages, p + 1))
655→                        }
656→                      />
657→                      <Text as="span" tone="subdued" variant="bodySm">
658→                        Page {currentPage} of {totalPages} (
659→                        {filteredEntries.length} results)
660→                      </Text>
661→                    </InlineStack>
662→                  </Box>
663→                )}
664→              </>
665→            )}
666→          </Card>
667→        </Layout.Section>
668→      </Layout>
669→      </Box>
670→
671→      {/* Add Entry Modal */}
672→      <Modal
673→        open={addModalOpen}
674→        onClose={() => {
675→          setAddModalOpen(false);
676→          setNewEmail("");
677→          setNewZipCode("");
678→          setNewNote("");
679→        }}
680→        title="Add Waitlist Entry"
681→        primaryAction={{ content: "Add to Waitlist", onAction: handleAdd }}
682→        secondaryActions={[
683→          {
684→            content: "Cancel",
685→            onAction: () => {
686→              setAddModalOpen(false);
687→              setNewEmail("");
688→              setNewZipCode("");
689→              setNewNote("");
690→            },
691→          },
692→        ]}
693→      >
694→        <Modal.Section>
695→          <BlockStack gap="400">
696→            {actionError && <Banner tone="critical">{actionError}</Banner>}
697→            <TextField
698→              label="Email"
699→              type="email"
