792→              onChange={setNewEmail}
793→              placeholder="customer@example.com"
794→              autoComplete="off"
795→            />
796→            <TextField
797→              label="Zip Code"
798→              value={newZipCode}
799→              onChange={setNewZipCode}
800→              placeholder="e.g. 33101"
801→              autoComplete="off"
802→            />
803→            <TextField
804→              label="Note (optional)"
805→              value={newNote}
806→              onChange={setNewNote}
807→              placeholder="Any additional notes..."
808→              autoComplete="off"
809→              multiline={2}
810→            />
811→          </BlockStack>
812→        </Modal.Section>
813→      </Modal>
814→
815→      {/* Bulk Notify Modal */}
816→      <Modal
817→        open={notifyModalOpen}
818→        onClose={() => {
819→          setNotifyModalOpen(false);
820→          setNotifyZip("");
821→        }}
822→        title="Notify Waitlist by Zip Code"
823→        primaryAction={{
824→          content: "Notify Waiting Customers",
825→          onAction: handleBulkNotify,
826→          disabled: !notifyZip.trim(),
827→          loading: fetcher.state !== "idle",
828→        }}
829→        secondaryActions={[
830→          {
831→            content: "Cancel",
832→            onAction: () => {
833→              setNotifyModalOpen(false);
834→              setNotifyZip("");
835→            },
836→          },
837→        ]}
838→      >
839→        <Modal.Section>
840→          <BlockStack gap="400">
841→            {actionError && <Banner tone="critical">{actionError}</Banner>}
842→            <Text as="p">
843→              Enter a zip code to mark all waiting customers for that area as
844→              &quot;Notified&quot; and retrieve their email addresses. Use this
845→              when you&apos;ve expanded delivery to a new area and want to
846→              contact waitlisted customers.
847→            </Text>
848→            <TextField
849→              label="Zip Code"
850→              value={notifyZip}
851→              onChange={setNotifyZip}
852→              placeholder="e.g. 33101"
853→              autoComplete="off"
854→            />
855→          </BlockStack>
856→        </Modal.Section>
857→      </Modal>
858→
859→      {/* Notification Result Modal */}
860→      <Modal
861→        open={notifyResultModalOpen}
862→        onClose={() => {
863→          setNotifyResultModalOpen(false);
864→          setCopySuccess(false);
865→        }}
866→        title={`Notify Waitlist for ZIP ${notifyResult?.zipCode ?? ""}`}
867→        primaryAction={{
868→          content: copySuccess ? "Copied!" : "Copy Emails",
869→          onAction: handleCopyEmails,
870→          disabled: !notifyResult || notifyResult.emails.length === 0,
871→        }}
872→        secondaryActions={
873→          notifyResult && notifyResult.emails.length > 0
874→            ? [
875→                {
876→                  content: "Open in Email Client",
877→                  url: `mailto:${notifyResult.emails.join(",")}?subject=${encodeURIComponent(`Great news! We now deliver to your area (ZIP ${notifyResult.zipCode})`)}&body=${encodeURIComponent(`Hi!\n\nWe wanted to let you know that we now deliver to your ZIP code ${notifyResult.zipCode}.\n\nThank you for your patience!`)}`,
878→                  external: true,
879→                },
880→                {
881→                  content: "Close",
882→                  onAction: () => {
883→                    setNotifyResultModalOpen(false);
884→                    setCopySuccess(false);
885→                  },
886→                },
887→              ]
888→            : [
889→                {
890→                  content: "Close",
891→                  onAction: () => {
892→                    setNotifyResultModalOpen(false);
893→                    setCopySuccess(false);
894→                  },
895→                },
896→              ]
897→        }
898→      >
899→        <Modal.Section>
900→          <BlockStack gap="400">
901→            {notifyResult && notifyResult.count > 0 ? (
902→              <>
903→                <Banner tone="success">
904→                  Updated {notifyResult.count} customer
905→                  {notifyResult.count === 1 ? "" : "s"} to &quot;Notified&quot;
906→                  status for ZIP code {notifyResult.zipCode}.
907→                </Banner>
908→                <Text as="p">
909→                  Copy these email addresses and paste them into your preferred
910→                  email client, or click &quot;Open in Email Client&quot; to
911→                  launch a pre-filled email.
912→                </Text>
913→                <TextField
914→                  label="Customer Emails"
915→                  value={notifyResult.emails.join(", ")}
916→                  onChange={() => {}}
917→                  multiline={4}
918→                  autoComplete="off"
919→                  readOnly
920→                />
921→              </>
922→            ) : (
923→              <Banner tone="info">
924→                No customers with &quot;Waiting&quot; status found for ZIP code{" "}
925→                {notifyResult?.zipCode ?? ""}. They may have already been
926→                notified.
927→              </Banner>
928→            )}
929→          </BlockStack>
930→        </Modal.Section>
931→      </Modal>
932→    </Page>
933→  );
934→}
935→
936→export const headers: HeadersFunction = (headersArgs) => {
937→  return boundary.headers(headersArgs);
938→};
